const api = new WinnerApi(WINNER_CONFIG.apiUrl);
const UNKNOWN = "UNAVAILABLE";
const record = (value: unknown): Record<string, unknown> => value && typeof value === "object" ? value as Record<string, unknown> : {};
const stringValue = (value: unknown) => typeof value === "string" && value.trim() ? value : null;
const numberValue = (value: unknown) => typeof value === "number" && Number.isFinite(value) ? value : null;
const chainLabel = (chain: string | null | undefined) => chain === "ROBINHOOD" ? "RH" : chain === "ETHEREUM" ? "ETH" : chain === "SOLANA" ? "SOL" : chain ?? "â€”";
const lifecycleLabel = (value: string | null | undefined) => value?.replaceAll("_", " ") ?? UNKNOWN;
const displayed = (value: string | null | undefined, formatter = (x: string) => x) => value == null || value === "" ? UNKNOWN : formatter(value);
const safeDate = (value: string | null | undefined) => value ? new Date(value).toLocaleString() : UNKNOWN;

function normalize(raw: unknown): OriginMarket {
  const r = record(raw); const life = record(r.lifecycle); const integrity = record(r.integrity); const perp = record(r.perp); const derivatives = record(r.derivatives); const freshness = record(r.freshness); const provider = record(r.providerState); const token = record(r.token);
  const marketId = stringValue(r.marketId) ?? stringValue(r.id) ?? "unknown";
  const chain = (stringValue(r.chain)?.toUpperCase() ?? "ARC") as OriginMarket["chain"];
  const history = Array.isArray(r.history) ? r.history.flatMap((point) => { const p = record(point); const observedAt = stringValue(p.observedAt); const priceUsd = stringValue(p.priceUsd); return observedAt && priceUsd ? [{ observedAt, priceUsd }] : []; }) : [];
  const observations = Array.isArray(integrity.observations) ? integrity.observations.flatMap((item) => { const observation = record(item); const providerName = stringValue(observation.provider); const status = stringValue(observation.status); return providerName && status ? [{ provider: providerName, status: status as OriginMarket["providerState"]["status"], observedAt: stringValue(observation.observedAt), fetchedAt: stringValue(observation.fetchedAt), blockOrSlot: stringValue(observation.blockOrSlot), evidenceHash: stringValue(observation.evidenceHash), reason: stringValue(observation.reason) }] : []; }) : [];
  return {
    marketId, chain, tokenAddress: stringValue(r.tokenAddress) ?? stringValue(token.address) ?? marketId, symbol: stringValue(r.symbol) ?? stringValue(token.symbol), name: stringValue(r.name) ?? stringValue(token.name), decimals: numberValue(r.decimals) ?? numberValue(token.decimals), imageUrl: stringValue(r.imageUrl) ?? stringValue(token.imageUrl), sourceUrl: stringValue(r.sourceUrl), originPlatform: stringValue(r.originPlatform),
    lifecycle: { status: (stringValue(life.status) ?? stringValue(r.lifecycleStatus) ?? "DISCOVERED") as OriginMarket["lifecycle"]["status"], observedAt: stringValue(life.observedAt), confidenceBps: numberValue(life.confidenceBps), evidenceHash: stringValue(life.evidenceHash) },
    priceUsd: stringValue(r.priceUsd) ?? stringValue(r.price), priceChange24hBps: numberValue(r.priceChange24hBps), volume24hUsd: stringValue(r.volume24hUsd) ?? stringValue(r.volumeUsd), transactions24h: numberValue(r.transactions24h), originSpotLiquidityUsd: stringValue(r.originSpotLiquidityUsd) ?? stringValue(r.liquidityUsd), originDepth2PctUsd: stringValue(r.originDepth2PctUsd), holders: numberValue(r.holders), top10ConcentrationBps: numberValue(r.top10ConcentrationBps), largestClusterBps: numberValue(r.largestClusterBps),
    integrity: { status: (stringValue(integrity.status) ?? "UNKNOWN") as OriginMarket["integrity"]["status"], reasonCodes: Array.isArray(integrity.reasonCodes) ? integrity.reasonCodes.filter((value): value is string => typeof value === "string") : [], observations },
    derivatives: { status: (stringValue(derivatives.status) ?? "NOT_REGISTERED") as OriginMarket["derivatives"]["status"], safeOiUsd: stringValue(derivatives.safeOiUsd), safePositionUsd: stringValue(derivatives.safePositionUsd), maxLeverage: stringValue(derivatives.maxLeverage), oracleQuality: stringValue(derivatives.oracleQuality), sourceIndependence: numberValue(derivatives.sourceIndependence), reasonCodes: Array.isArray(derivatives.reasonCodes) ? derivatives.reasonCodes.filter((value): value is string => typeof value === "string") : [] },
    perp: { status: (stringValue(perp.status) ?? "NOT_REGISTERED") as OriginMarket["perp"]["status"], deploymentId: stringValue(perp.deploymentId), marketId: stringValue(perp.marketId), currentOiUsd: stringValue(perp.currentOiUsd), capacityUsd: stringValue(perp.capacityUsd), qualificationHash: stringValue(perp.qualificationHash), riskRuleVersion: stringValue(perp.riskRuleVersion) },
    providerState: { status: (stringValue(provider.status) ?? "UNAVAILABLE") as OriginMarket["providerState"]["status"], fetchedAt: stringValue(provider.fetchedAt), reason: stringValue(provider.reason) }, freshness: { status: (stringValue(freshness.status) ?? "UNAVAILABLE") as OriginMarket["freshness"]["status"], observedAt: stringValue(freshness.observedAt), maxAgeSeconds: numberValue(freshness.maxAgeSeconds) }, history,
  };
}

function useProductData() {
  const [page, setPage] = useState<MarketPage>({ items: [], nextCursor: null }); const [health, setHealth] = useState<Health | null>(null); const [error, setError] = useState<string | null>(null); const [stream, setStream] = useState<"LIVE" | "RECONNECTING" | "STALE" | "OFFLINE">("RECONNECTING"); const [, setEvents] = useState<RealtimeEvent[]>([]);
  const refresh = useCallback(async (params: Record<string, string | number | undefined> = {}) => { try { const result = await api.markets(params); setPage({ ...result, items: (result.items ?? []).map(normalize) }); setError(null); } catch (errorValue) { setError(errorValue instanceof Error ? errorValue.message : "API_UNAVAILABLE"); } }, []);
  useEffect(() => { void refresh({ limit: 50 }); void api.health().then(setHealth).catch(() => setHealth(null)); return subscribeRealtime(WINNER_CONFIG.apiUrl, (event) => setEvents((current) => [event, ...current].slice(0, 30)), setStream); }, [refresh]);
  return { page, health, error, stream, refresh };
}

function useWatchlist() {
  const [items, setItems] = useState<string[]>(() => { try { const saved = window.localStorage.getItem("arcmemeperps.watchlist"); return saved ? JSON.parse(saved) as string[] : []; } catch { return []; } });
  const update = (next: string[]) => { setItems(next); try { window.localStorage.setItem("arcmemeperps.watchlist", JSON.stringify(next)); } catch { /* local-only fallback */ } };
  return { items, has: (id: string) => items.includes(id), toggle: (id: string) => update(items.includes(id) ? items.filter((item) => item !== id) : [...items, id]) };
}

function useResource(marketId: string | undefined, resource: string | null) {
  const [state, setState] = useState<{ value: unknown; loading: boolean; error: string | null }>({ value: null, loading: false, error: null });
  useEffect(() => { if (!marketId || !resource) return; let active = true; setState({ value: null, loading: true, error: null }); void api.resource(marketId, resource).then((value) => { if (active) setState({ value, loading: false, error: null }); }).catch((errorValue) => { if (active) setState({ value: null, loading: false, error: errorValue instanceof Error ? errorValue.message : "API_UNAVAILABLE" }); }); return () => { active = false; }; }, [marketId, resource]);
  return state;
}

function Logo() { return <Link className="brand" to="/"><span className="brand-mark">A</span><span>ArcMeme<span className="brand-accent">Perps</span></span></Link>; }
function StatusPill({ value, tone, label }: { value: string; tone?: "good" | "warn" | "bad" | "muted"; label?: string }) { return <span className={`status-pill ${tone ?? statusClass(value)}`}><i />{label ?? value.replaceAll("_", " ")}</span>; }
function productState(market: OriginMarket) { if (market.perp.status === "LIVE") return { label: "LIVE PERP", tone: "good" as const }; if (market.perp.status === "PAUSED") return { label: "PAUSED", tone: "warn" as const }; if (market.perp.status === "CLOSE_ONLY") return { label: "CLOSE ONLY", tone: "warn" as const }; if (market.integrity.status === "REJECTED" || market.perp.status === "BLOCKED") return { label: "REJECTED", tone: "bad" as const }; if (market.integrity.status === "PENDING") return { label: "PENDING EVIDENCE", tone: "warn" as const }; if (market.integrity.status === "QUALIFIED" && market.perp.status === "ELIGIBLE") return { label: "QUALIFIED", tone: "good" as const }; if (market.integrity.status === "WATCH") return { label: "WATCH", tone: "warn" as const }; return { label: "DISCOVERY", tone: "muted" as const }; }

function Header({ wallet, stream, onSearch }: { wallet: ReturnType<typeof useWallet>; stream: string; onSearch: (value: string) => void }) {
  const [query, setQuery] = useState(""); const navigate = useNavigate();
  const submit = (event: FormEvent) => { event.preventDefault(); if (query.trim()) { onSearch(query.trim()); void navigate(`/markets?q=${encodeURIComponent(query.trim())}`); } };
  return <header className="topbar"><Logo /><form className="global-search" onSubmit={submit}><span className="search-icon">âŒ•</span><input aria-label="Search markets" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search token, address or market ID" /><kbd>âŒ˜ K</kbd></form><div className="top-actions"><span className="network-chip"><span className="network-dot" />{WINNER_CONFIG.chainName}</span><span className={`stream-dot ${stream === "LIVE" ? "live" : ""}`} title={`Realtime ${stream}`} /><Link className="icon-button" to="/notifications" aria-label="Notifications">â™¢</Link>{wallet.state.address ? <button className="wallet-button" onClick={() => void wallet.disconnect()}><span className="wallet-dot" />{shorten(wallet.state.address)}</button> : <button className="button button-primary compact" onClick={() => void wallet.connect()}>Connect wallet</button>}</div></header>;
}

const primary = [{ to: "/markets", label: "Markets", icon: "â—ˆ" }, { to: "/new", label: "New", icon: "âœ¦" }, { to: "/watchlist", label: "Watchlist", icon: "â˜†" }, { to: "/portfolio", label: "Portfolio", icon: "â—Œ" }, { to: "/activity", label: "Activity", icon: "â‰¡" }];
function Shell({ wallet, stream, onSearch }: { wallet: ReturnType<typeof useWallet>; stream: string; onSearch: (value: string) => void }) { return <div className="app-shell"><Header wallet={wallet} stream={stream} onSearch={onSearch} /><div className="shell-body"><aside className="side-nav"><div className="side-section"><span className="side-label">Trade</span>{primary.map((item) => <NavLink key={item.to} to={item.to} className={({ isActive }) => `side-link ${isActive ? "active" : ""}`}><span>{item.icon}</span>{item.label}</NavLink>)}</div><div className="side-section"><span className="side-label">More</span><NavLink to="/earn" className="side-link"><span>â—‡</span>Earn / LP</NavLink><NavLink to="/competitions" className="side-link"><span>âœ§</span>Competitions</NavLink><NavLink to="/profile" className="side-link"><span>â—Ž</span>Profile</NavLink></div><div className="side-bottom"><NavLink to="/proof" className="side-link"><span>â†—</span>Protocol / Proof</NavLink><NavLink to="/settings" className="side-link"><span>âš™</span>Settings</NavLink><div className="side-footer"><b>ARC MAINNET</b><span>{WINNER_CONFIG.deploymentStatus === "DEPLOYMENT_PENDING" ? "Deployment pending" : "Qualification-gated perps"}</span></div></div></aside><main className="content"><Outlet /></main></div><nav className="mobile-nav">{primary.slice(0, 5).map((item) => <NavLink key={item.to} to={item.to} className={({ isActive }) => isActive ? "active" : ""}><span>{item.icon}</span>{item.label}</NavLink>)}</nav></div>; }
function PageIntro({ eyebrow, title, copy, action }: { eyebrow: string; title: string; copy?: string; action?: ReactNode }) { return <div className="page-intro"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1>{copy && <p>{copy}</p>}</div>{action}</div>; }
function Empty({ title, copy, action }: { title: string; copy: string; action?: ReactNode }) { return <div className="empty"><div className="empty-orbit"><span /></div><h3>{title}</h3><p>{copy}</p>{action}</div>; }
function Metric({ label, value, note }: { label: string; value: ReactNode; note?: string }) { return <div className="metric"><span>{label}</span><strong>{value}</strong>{note && <small>{note}</small>}</div>; }
function TokenAvatar({ market, large = false }: { market: OriginMarket; large?: boolean }) { const initials = (market.symbol ?? market.name ?? "?").slice(0, 2).toUpperCase(); return market.imageUrl ? <img className={`token-avatar ${large ? "large" : ""}`} src={market.imageUrl} alt="" onError={(event) => { event.currentTarget.style.display = "none"; }} /> : <span className={`token-avatar ${large ? "large" : ""}`}>{initials}</span>; }

function MarketRow({ market }: { market: OriginMarket }) {
  const state = productState(market);
  return <Link to={`/markets/${encodeURIComponent(market.marketId)}`} className="market-row-link"><div className="market-cell token-cell"><TokenAvatar market={market} /><div className="token-copy"><strong>{market.symbol ?? "UNKNOWN"}</strong><span>{market.name ?? "Name unavailable"}</span></div></div><div className="market-cell mono chain-cell"><span className={`chain-dot chain-${market.chain.toLowerCase()}`} />{chainLabel(market.chain)}</div><div className="market-cell mono muted-text">{ageLabel(market.lifecycle.observedAt)}</div><div className="market-cell mono price-cell">{displayed(market.priceUsd, formatUsd)}</div><div className={`market-cell mono ${market.priceChange24hBps === null ? "muted-text" : market.priceChange24hBps >= 0 ? "positive" : "negative"}`}>{market.priceChange24hBps === null ? UNKNOWN : formatPercentBps(market.priceChange24hBps)}</div><div className="market-cell mono">{displayed(market.originSpotLiquidityUsd, formatUsd)}</div><div className="market-cell mono">{displayed(market.volume24hUsd, formatUsd)}</div><div className="market-cell mono">{market.transactions24h === null ? UNKNOWN : formatDecimal(String(market.transactions24h), 0)}</div><div className="market-cell mono">{market.holders === null ? UNKNOWN : formatDecimal(String(market.holders), 0)}</div><div className="market-cell mono">{market.top10ConcentrationBps === null ? UNKNOWN : formatPercentBps(market.top10ConcentrationBps)}</div><div className="market-cell"><StatusPill value={market.lifecycle.status} tone="muted" label={lifecycleLabel(market.lifecycle.status)} /></div><div className="market-cell"><StatusPill value={state.label} tone={state.tone} label={state.label} /></div><div className="market-cell mono max-lev">{market.derivatives.maxLeverage ?? "â€”"}</div></Link>;
}

function CategoryBar({ selected, onSelect, markets }: { selected: string; onSelect: (value: string) => void; markets: OriginMarket[] }) {
  const categories = [["TRENDING", "Trending", markets.length ? markets.filter((market) => (market.transactions24h ?? 0) > 0).length : 0], ["NEW", "New", markets.filter((market) => market.lifecycle.status === "NEW").length], ["BONDING", "Bonding", markets.filter((market) => ["BONDING", "BONDED"].includes(market.lifecycle.status)).length], ["GRADUATED", "Graduated", markets.filter((market) => ["GRADUATED", "MIGRATED"].includes(market.lifecycle.status)).length], ["DEX_LIVE", "DEX live", markets.filter((market) => ["DEX_LIVE", "ESTABLISHED"].includes(market.lifecycle.status)).length], ["PERPS", "Perps", markets.filter((market) => market.perp.status === "LIVE" || market.perp.status === "ELIGIBLE").length]];
  return <div className="category-bar" role="tablist" aria-label="Market categories">{categories.map(([key, label, count]) => <button key={String(key)} className={selected === String(key) ? "active" : ""} onClick={() => onSelect(String(key))} role="tab" aria-selected={selected === String(key)}><span>{String(label)}</span><b>{count ? String(count) : "â€”"}</b></button>)}</div>;
}

function MarketExplorer({ data, refresh, error, search, view, watchlist }: { data: ReturnType<typeof useProductData>; refresh: (params?: Record<string, string | number | undefined>) => Promise<void>; error: string | null; search?: string; view: "MARKETS" | "NEW" | "WATCHLIST"; watchlist: ReturnType<typeof useWatchlist> }) {
  const [chain, setChain] = useState("ALL"); const [lifecycle, setLifecycle] = useState("ALL"); const [query, setQuery] = useState(search ?? ""); const [category, setCategory] = useState(view === "NEW" ? "NEW" : "TRENDING");
  useEffect(() => { if (search) { setQuery(search); void refresh({ q: search, limit: 50 }); } }, [search, refresh]);
  const displayItems = useMemo(() => { let items = data.page.items.filter((market) => view !== "WATCHLIST" || watchlist.has(market.marketId)); if (category === "NEW") items = items.filter((market) => market.lifecycle.status === "NEW"); if (category === "BONDING") items = items.filter((market) => ["BONDING", "BONDED"].includes(market.lifecycle.status)); if (category === "GRADUATED") items = items.filter((market) => ["GRADUATED", "MIGRATED"].includes(market.lifecycle.status)); if (category === "DEX_LIVE") items = items.filter((market) => ["DEX_LIVE", "ESTABLISHED"].includes(market.lifecycle.status)); if (category === "PERPS") items = items.filter((market) => market.perp.status === "LIVE" || market.perp.status === "ELIGIBLE"); if (category === "TRENDING") items = [...items].sort((left, right) => (right.transactions24h ?? 0) - (left.transactions24h ?? 0)); return items; }, [category, data.page.items, view, watchlist]);
  const apply = (next: { chain?: string; lifecycle?: string; query?: string } = {}) => { const state = { chain: next.chain ?? chain, lifecycle: next.lifecycle ?? lifecycle, query: next.query ?? query }; void refresh({ chain: state.chain, lifecycle: state.lifecycle, q: state.query, limit: 50 }); };
  const title = view === "WATCHLIST" ? "Your watchlist" : view === "NEW" ? "New markets" : "Markets"; const copy = view === "WATCHLIST" ? "Keep a close eye on the markets you are researching." : view === "NEW" ? "Fresh origin markets, shown with their age and evidence state." : "Discover meme markets across chains. Read the evidence before leverage.";
  const emptyTitle = category === "PERPS" ? "No market currently meets the complete activation policy." : "No markets match this view";
  const emptyCopy = category === "PERPS" ? "Discovery remains available across the observed universe. A market becomes tradable only after core safety, derivatives capacity, qualification, Arc activation, and live oracle checks all pass." : "Try another chain, stage, or exact address. Unsupported data stays unavailable instead of becoming an empty success.";
  return <section className="page explorer-page"><PageIntro eyebrow="Market discovery" title={title} copy={copy} action={<span className="live-count"><span className="pulse" />{data.page.discoveryCount ?? data.page.items.length} observed</span>} /><div className="market-toolbar"><div className="toolbar-search"><span>âŒ•</span><input value={query} onChange={(event) => setQuery(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter") apply({ query: query.trim() }); }} placeholder="Search symbol, name or exact address" aria-label="Filter market universe" /></div><select value={chain} onChange={(event) => { setChain(event.target.value); apply({ chain: event.target.value }); }}>{CHAIN_OPTIONS.filter((item) => item !== "ARC").map((item) => <option key={item} value={item}>{item === "ALL" ? "All chains" : chainLabel(item)}</option>)}</select><select value={lifecycle} onChange={(event) => { setLifecycle(event.target.value); apply({ lifecycle: event.target.value }); }}><option value="ALL">All stages</option>{LIFECYCLE_OPTIONS.filter((item) => item !== "ALL").map((item) => <option key={item} value={item}>{lifecycleLabel(item)}</option>)}</select></div><CategoryBar selected={category} onSelect={setCategory} markets={data.page.items} /><div className="chain-tabs" role="tablist" aria-label="Chain filter">{["ALL", "SOLANA", "BASE", "BNB", "ETHEREUM", "ROBINHOOD"].map((item) => <button key={item} role="tab" aria-selected={chain === item} className={chain === item ? "active" : ""} onClick={() => { setChain(item); apply({ chain: item }); }}>{item === "ALL" ? "All" : chainLabel(item)}</button>)}</div>{category === "PERPS" && <div className="perp-truth"><span className="perp-icon">â†—</span><div><b>{data.page.perpCount ?? 0} live perp markets</b><span>No market currently meets the complete activation policy. Perp markets appear here only after passing qualification and capacity policy.</span></div></div>}{error && <div className="notice notice-bad"><b>Market data is unavailable.</b><span>{error}. The interface is not replacing missing observations with zeros.</span></div>}<div className="table-meta"><span>{displayItems.length} shown</span><span>Identity = chain + canonical address</span><span className="coverage-key"><i className="key-dot strong" />Evidence state is always visible</span></div>{view === "WATCHLIST" && !watchlist.items.length ? <div className="panel"><Empty title="Your watchlist is empty" copy="Open a market and save it here while you research. This list stays local to this browser." /></div> : displayItems.length ? <div className="market-table"><div className="market-head"><span>Token</span><span>Chain</span><span>Age</span><span>Price</span><span>24h</span><span>Liquidity</span><span>24h vol</span><span>Txns</span><span>Holders</span><span>Top 10</span><span>Lifecycle</span><span>Risk</span><span>Max lev.</span></div>{displayItems.map((market) => <MarketRow key={market.marketId} market={market} />)}</div> : <div className="panel"><Empty title={emptyTitle} copy={emptyCopy} /></div>}</section>;
}

function MiniChart({ history }: { history: OriginMarket["history"] }) { const [range, setRange] = useState("1D"); if (history.length < 2) return <div className="chart-empty"><span>History unavailable</span><p>There are not enough real observations for a chart yet. No synthetic points are rendered.</p></div>; const numeric = history.map((item) => Number(item.priceUsd)); const min = Math.min(...numeric); const max = Math.max(...numeric); const points = history.map((item, index) => `${(index / (history.length - 1)) * 100},${100 - ((Number(item.priceUsd) - min) / Math.max(max - min, 0.00000001)) * 82 - 8}`).join(" "); return <div className="chart-wrap"><div className="chart-controls"><div className="range-tabs">{["1H", "4H", "1D", "1W"].map((item) => <button key={item} className={range === item ? "active" : ""} onClick={() => setRange(item)}>{item}</button>)}</div><span>{history.length} observed points Â· {range} view</span></div><div className="chart"><svg viewBox="0 0 100 100" preserveAspectRatio="none" role="img" aria-label="Observed market price history"><defs><linearGradient id="chart-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="rgba(215,240,184,.2)" /><stop offset="1" stopColor="rgba(215,240,184,0)" /></linearGradient></defs><polygon points={`0,100 ${points} 100,100`} fill="url(#chart-fill)" /><polyline points={points} fill="none" vectorEffect="non-scaling-stroke" /></svg></div><div className="chart-caption"><span>{safeDate(history[0]?.observedAt)}</span><span>{safeDate(history.at(-1)?.observedAt)}</span></div></div>; }

type PassportRow = { label: string; value: string; note: string; tone?: "good" | "warn" | "bad" | "muted" };
function passportRows(market: OriginMarket): PassportRow[] { const status = market.integrity.status; return [{ label: "Mint authority", value: market.chain === "SOLANA" ? UNKNOWN : "Not applicable", note: "Chain-specific authority model", tone: market.chain === "SOLANA" ? "warn" : "muted" }, { label: "Freeze authority", value: market.chain === "SOLANA" ? UNKNOWN : "Not applicable", note: "Chain-specific authority model", tone: market.chain === "SOLANA" ? "warn" : "muted" }, { label: "Admin control", value: UNKNOWN, note: "Current privilege evidence", tone: "warn" }, { label: "Upgradeability", value: UNKNOWN, note: "Proxy and implementation evidence", tone: "warn" }, { label: "Transfer safety", value: UNKNOWN, note: "Sellability and restriction checks", tone: "warn" }, { label: "LP control", value: UNKNOWN, note: "Withdrawal and lock evidence", tone: "warn" }, { label: "Largest holder", value: market.top10ConcentrationBps === null ? UNKNOWN : formatPercentBps(market.top10ConcentrationBps), note: "Top-holder evidence is separate from raw supply", tone: market.top10ConcentrationBps === null ? "warn" : "muted" }, { label: "Connected cluster", value: market.largestClusterBps === null ? UNKNOWN : formatPercentBps(market.largestClusterBps), note: "Relationship graph coverage", tone: market.largestClusterBps === null ? "warn" : "muted" }, { label: "Bundle", value: UNKNOWN, note: "Launch distribution evidence", tone: "warn" }, { label: "Activity", value: market.transactions24h === null ? UNKNOWN : "Observed", note: "Activity is not a safety guarantee", tone: market.transactions24h === null ? "warn" : "muted" }, { label: "Depth Â±2%", value: market.originDepth2PctUsd ? formatUsd(market.originDepth2PctUsd) : UNKNOWN, note: "Executable origin depth", tone: market.originDepth2PctUsd ? "muted" : "warn" }, { label: "Oracle", value: market.derivatives.oracleQuality ?? UNKNOWN, note: market.freshness.status === "AVAILABLE" ? "Freshness available" : "Freshness unavailable", tone: market.derivatives.oracleQuality ? "muted" : "warn" }, { label: "Core state", value: status === "QUALIFIED" ? "Qualified" : status === "REJECTED" ? "Rejected" : status === "PENDING" ? "Pending evidence" : status, note: "Audited policy state", tone: status === "QUALIFIED" ? "good" : status === "REJECTED" ? "bad" : "warn" }]; }
function RiskPassport({ market, onProvenance }: { market: OriginMarket; onProvenance: (row: PassportRow) => void }) { return <section className="passport panel"><div className="passport-head"><div><div className="eyebrow">Risk passport</div><h2>Evidence before leverage</h2></div><StatusPill value={market.integrity.status} tone={market.integrity.status === "QUALIFIED" ? "good" : market.integrity.status === "REJECTED" ? "bad" : "warn"} label={market.integrity.status === "PENDING" ? "PENDING EVIDENCE" : market.integrity.status} /></div><div className="passport-list">{passportRows(market).map((row) => <button className="passport-row" key={row.label} onClick={() => onProvenance(row)}><span>{row.label}</span><strong className={row.tone === "warn" ? "unknown" : row.tone === "bad" ? "negative" : row.tone === "good" ? "positive" : ""}>{row.value}</strong><small>{row.note}</small><span className="row-arrow">â†—</span></button>)}</div><div className="passport-foot">Observed {ageLabel(market.freshness.observedAt)} Â· provider {market.providerState.status} Â· {market.integrity.reasonCodes[0] ?? "No reason code supplied"}</div></section>; }
function EvidenceCoverage({ market }: { market: OriginMarket }) { const domains = [["Authority", market.integrity.observations.length ? "PARTIAL" : "WEAK"], ["Transfer safety", market.integrity.status === "REJECTED" ? "PARTIAL" : "WEAK"], ["Liquidity control", market.originSpotLiquidityUsd ? "PARTIAL" : "WEAK"], ["Holders", market.holders === null ? "WEAK" : "PARTIAL"], ["Clusters", market.largestClusterBps === null ? "WEAK" : "PARTIAL"], ["History", market.history.length > 1 ? "STRONG" : "WEAK"], ["Depth", market.originDepth2PctUsd ? "STRONG" : "WEAK"], ["Oracle", market.derivatives.oracleQuality ? "STRONG" : "WEAK"]]; const overall = domains.filter(([, value]) => value === "STRONG").length >= 4 ? "STRONG" : domains.some(([, value]) => value === "WEAK") ? "PARTIAL" : "COMPLETE"; return <section className="coverage panel"><div className="coverage-head"><div><div className="eyebrow">Evidence coverage</div><h3>{overall}</h3></div><span className="micro">Unknown evidence stays visible</span></div><div className="coverage-grid">{domains.map(([label, value]) => <div key={label}><span>{label}</span><b className={`coverage-${String(value).toLowerCase()}`}>{value}</b></div>)}</div></section>; }
function ProvenanceDrawer({ market, row, onClose }: { market: OriginMarket; row: PassportRow; onClose: () => void }) { const observation = market.integrity.observations[0]; return <div className="drawer-backdrop" onClick={onClose}><aside className="provenance-drawer" role="dialog" aria-modal="true" aria-label={`${row.label} provenance`} onClick={(event) => event.stopPropagation()}><button className="drawer-close" onClick={onClose} aria-label="Close provenance">Ã—</button><div className="eyebrow">Provenance</div><h2>{row.label}</h2><div className="drawer-status"><StatusPill value={row.value} tone={row.tone ?? "muted"} /><span>{row.note}</span></div><div className="provenance-list"><div><span>Source</span><b>{observation?.provider ?? market.providerState.status}</b></div><div><span>Chain</span><b>{chainLabel(market.chain)}</b></div><div><span>Token</span><code>{shorten(market.tokenAddress, 10)}</code></div><div><span>Observed</span><b>{safeDate(observation?.observedAt ?? market.freshness.observedAt)}</b></div><div><span>Fetched</span><b>{safeDate(observation?.fetchedAt ?? market.providerState.fetchedAt)}</b></div><div><span>Block / slot</span><b>{observation?.blockOrSlot ?? UNKNOWN}</b></div><div><span>Evidence status</span><b>{observation?.status ?? market.providerState.status}</b></div><div><span>Reason</span><b>{observation?.reason ?? row.note}</b></div></div><details className="advanced-details"><summary>Advanced evidence identity</summary><code>{(market.lifecycle.evidenceHash ?? market.integrity.reasonCodes.join(" Â· ")) || "No evidence hash persisted"}</code></details></aside></div>; }
function ResourceState({ state, title, copy }: { state: ReturnType<typeof useResource>; title: string; copy: string }) { if (state.loading) return <div className="resource-state"><span className="skeleton-line" /><span className="skeleton-line short" /></div>; if (state.error) return <Empty title={`${title} unavailable`} copy={`${copy} The configured API returned an error without replacing it with zeros.`} />; const response = record(state.value); const status = stringValue(response.status); if (status && status !== "AVAILABLE") return <Empty title={`${title} unavailable`} copy={stringValue(response.reason) ?? copy} />; return null; }
function textValue(value: unknown, fallback: string) { return typeof value === "string" || typeof value === "number" ? String(value) : fallback; }
function HoldersPanel({ state }: { state: ReturnType<typeof useResource> }) { const response = record(state.value); const evidence = record(response.holderEvidence); const holders = Array.isArray(evidence.holders) ? evidence.holders : Array.isArray(response.holders) ? response.holders : []; if (!holders.length) return <><ResourceState state={state} title="Holder evidence" copy="Holder records are not available for this market." />{!state.loading && !state.error && !state.value && <Empty title="Holder evidence unavailable" copy="No indexed holder census was returned for this token." />}</>; return <div className="evidence-table"><div className="evidence-row evidence-head"><span>Rank</span><span>Address</span><span>Share</span><span>Class</span></div>{holders.slice(0, 20).map((holder, index) => { const item = record(holder); return <div className="evidence-row" key={stringValue(item.address) ?? String(index)}><span>{index + 1}</span><code>{shorten(stringValue(item.address), 8)}</code><b>{textValue(item.sharePct ?? item.percentage, UNKNOWN)}</b><StatusPill value={textValue(item.classification, "UNKNOWN")} tone={item.classification === "BURN" || item.classification === "POOL" ? "muted" : "warn"} label={textValue(item.classification, "UNKNOWN")} /></div>; })}</div>; }
function DetailEvidence({ tab, market, onProvenance }: { tab: string; market: OriginMarket; onProvenance: (row: PassportRow) => void }) { const resourceName = tab === "Trades" ? "activity" : tab === "Holders" ? "holders" : tab === "Deployer" ? "deployer" : tab === "Liquidity" ? "depth" : tab === "Proof" ? "proof" : tab === "Risk" ? "risk" : null; const state = useResource(market.marketId, resourceName); if (tab === "Overview") return <div className="overview-stack"><RiskPassport market={market} onProvenance={onProvenance} /><EvidenceCoverage market={market} /></div>; if (tab === "Risk") return <RiskPassport market={market} onProvenance={onProvenance} />; if (tab === "Holders") return <section className="panel evidence-panel"><div className="panel-heading"><div><div className="eyebrow">Distribution</div><h2>Holder concentration</h2></div><span className="micro">Raw and non-system views stay distinct</span></div><div className="holder-summary"><Metric label="Holders" value={market.holders === null ? UNKNOWN : formatDecimal(String(market.holders), 0)} /><Metric label="Top 10" value={market.top10ConcentrationBps === null ? UNKNOWN : formatPercentBps(market.top10ConcentrationBps)} /><Metric label="Cluster" value={market.largestClusterBps === null ? UNKNOWN : formatPercentBps(market.largestClusterBps)} /></div><HoldersPanel state={state} /></section>; if (tab === "Liquidity") return <section className="panel evidence-panel"><div className="panel-heading"><div><div className="eyebrow">Origin liquidity</div><h2>Verified pool surface</h2></div><span className="micro">Provider copies are not separate pools</span></div><div className="holder-summary"><Metric label="Spot liquidity" value={displayed(market.originSpotLiquidityUsd, formatUsd)} note="Deduplicated origin observation" /><Metric label="Depth Â±2%" value={displayed(market.originDepth2PctUsd, formatUsd)} /><Metric label="Venue state" value={market.providerState.status} /></div><ResourceState state={state} title="Depth evidence" copy="Direct pool depth is not available for this market." />{!state.loading && !state.value && <Empty title="Pool detail unavailable" copy="The market summary is real, but per-pool depth and withdrawal evidence were not returned." />}</section>; return <section className="panel evidence-panel"><div className="panel-heading"><div><div className="eyebrow">{tab}</div><h2>{tab === "Proof" ? "Qualification provenance" : `${tab} evidence`}</h2></div><span className="micro">Provider-backed, when available</span></div><ResourceState state={state} title={`${tab} evidence`} copy={`No ${tab.toLowerCase()} evidence was returned for this market.`} />{!state.loading && !state.value && !state.error && <Empty title={`${tab} evidence unavailable`} copy="This surface stays explicit until the configured provider supplies a verifiable observation." />}{Boolean(state.value) && !state.loading && !state.error && <pre className="data-preview">{JSON.stringify(state.value, null, 2)}</pre>}</section>; }

function DeploymentPendingRail() { return <aside className="trade-rail"><div className="rail-kicker">Arc perps</div><div className="rail-heading"><div><h2>Deployment pending</h2><span>{WINNER_CONFIG.chainName}</span></div><StatusPill value="DEPLOYMENT_PENDING" tone="warn" label="NOT DEPLOYED" /></div><p>Trading stays disabled until the frozen Mainnet suite is funded, deployed, and verified. Discovery and Risk Passport remain available.</p><div className="rail-lock"><span>âŠ˜</span><div><b>No order action</b><small>There are currently 0 registered live Arc perp markets.</small></div></div><Link to="/proof" className="button button-secondary button-wide">How qualification works</Link></aside>; }

function TradingRail({ market, wallet }: { market: OriginMarket; wallet: ReturnType<typeof useWallet> }) {
  const [side, setSide] = useState<"LONG" | "SHORT">("LONG"); const [collateral, setCollateral] = useState(""); const [leverage, setLeverage] = useState("2"); const [size, setSize] = useState(""); const [pretrade, setPretrade] = useState<Pretrade | null>(null); const [review, setReview] = useState(false); const [flow, setFlow] = useState("DRAFT"); const [error, setError] = useState<string | null>(null);
  const load = async () => { setError(null); try { const raw = await api.pretrade(market.marketId, wallet.state.address ?? undefined); const next = { ...raw, marketId: raw.marketId || market.marketId, account: wallet.state.address, side, action: "OPEN" as const, collateralUsdUsdc: collateral, sizeUsdWad: size, expiry: raw.expiry ?? String(Math.floor(Date.now() / 1000) + 300), planHash: raw.planHash ?? null }; if (next.status !== "AVAILABLE") throw new Error(`PRETRADE_${next.status}`); setPretrade(next); setReview(true); } catch (errorValue) { setError(errorValue instanceof Error ? errorValue.message : "PRETRADE_UNAVAILABLE"); } };
  const sign = async () => { if (!pretrade) return; setFlow("AWAITING_SIGNATURE"); try { const latest = await api.pretrade(market.marketId, wallet.state.address ?? undefined); const current = { ...latest, marketId: latest.marketId || market.marketId, account: wallet.state.address, side, action: "OPEN" as const, collateralUsdUsdc: collateral, sizeUsdWad: size, expiry: latest.expiry ?? pretrade.expiry, planHash: latest.planHash ?? pretrade.planHash }; if (current.status !== "AVAILABLE" || !isPretradeIntact(pretrade, current)) { setFlow("DRAFT"); setReview(false); throw new Error("PRETRADE_INVALIDATED_REVIEW_AGAIN"); } const hashes = await wallet.submitPlan(pretrade); setFlow("WAITING_KEEPER"); setError(`Submitted ${shorten(hashes.order)}; waiting for keeper execution`); } catch (errorValue) { setFlow("FAILED"); setError(errorValue instanceof Error ? errorValue.message : "WALLET_WRITE_FAILED"); } };
  const state = productState(market); if (WINNER_CONFIG.deploymentStatus === "DEPLOYMENT_PENDING") return <DeploymentPendingRail />;
  if (market.perp.status !== "LIVE") return <aside className="trade-rail"><div className="rail-kicker">Arc perps</div><div className="rail-heading"><div><h2>{state.label === "REJECTED" ? "Not eligible" : state.label === "PENDING EVIDENCE" ? "Qualification in progress" : "Perps unavailable"}</h2><span>{market.symbol ? `$${market.symbol}` : "Origin market"}</span></div><StatusPill value={state.label} tone={state.tone} label={state.label} /></div><p>{state.label === "REJECTED" ? "This market has an explicit qualification failure. It cannot be opened for Arc leverage." : state.label === "PENDING EVIDENCE" ? "Waiting for applicable evidence. Discovery remains available while leverage stays disabled." : "Arc perp markets appear here only after passing the qualification and capacity policy."}</p><div className="rail-lock"><span>âŠ˜</span><div><b>No order action</b><small>There are currently 0 registered live Arc perp markets.</small></div></div><Link to="/proof" className="button button-secondary button-wide">How qualification works</Link></aside>;
  return <aside className="trade-rail"><div className="rail-kicker">Arc perp</div><div className="rail-heading"><div><h2>Trade {market.symbol ?? "market"}</h2><span>Bounded USDC execution</span></div><StatusPill value="LIVE" tone="good" label="LIVE PERP" /></div><div className="side-toggle"><button className={side === "LONG" ? "selected long" : ""} onClick={() => setSide("LONG")}>Long</button><button className={side === "SHORT" ? "selected short" : ""} onClick={() => setSide("SHORT")}>Short</button></div><label className="field"><span>Collateral Â· USDC</span><input inputMode="decimal" value={collateral} onChange={(event) => setCollateral(event.target.value)} placeholder="0.00" /></label><label className="field"><span>Leverage</span><input inputMode="decimal" value={leverage} onChange={(event) => setLeverage(event.target.value)} placeholder="2" /></label><label className="field"><span>Position size</span><input inputMode="decimal" value={size} onChange={(event) => setSize(event.target.value)} placeholder="0.00" /></label><div className="rail-facts"><Metric label="Entry reference" value={displayed(market.priceUsd, formatUsd)} /><Metric label="Oracle" value={market.freshness.status} /><Metric label="Max leverage" value={market.derivatives.maxLeverage ?? UNKNOWN} /><Metric label="Safe OI" value={displayed(market.derivatives.safeOiUsd, formatUsd)} /><Metric label="Capacity" value={displayed(market.perp.capacityUsd, formatUsd)} /><Metric label="Liquidation" value={UNKNOWN} /></div>{error && <div className="inline-error">{error}</div>}<button className="button button-primary button-wide" disabled={!collateral || !size || market.freshness.status !== "AVAILABLE"} onClick={() => void load()}>Review {side === "LONG" ? "Long" : "Short"}</button>{review && pretrade && <div className="review-overlay" role="dialog" aria-modal="true"><div className="review-sheet"><button className="close" onClick={() => { setReview(false); setFlow("DRAFT"); }} aria-label="Close review">Ã—</button><div className="eyebrow">Immutable review</div><h2>{side} {market.symbol ?? "market"}</h2><p>Review exactly what the wallet will authorize. Any material state change invalidates this sheet.</p><div className="review-grid">{[["Account", pretrade.account ? shorten(pretrade.account) : UNKNOWN], ["Chain", `${WINNER_CONFIG.chainName} Â· ${WINNER_CONFIG.chainId}`], ["Market", shorten(pretrade.marketId)], ["Action", pretrade.action ?? UNKNOWN], ["Collateral", pretrade.collateralUsdUsdc ?? UNKNOWN], ["Size", pretrade.sizeUsdWad ?? UNKNOWN], ["Leverage", leverage], ["Acceptable price", pretrade.acceptablePriceWad ?? UNKNOWN], ["Oracle sequence", pretrade.oracle?.sequence ?? UNKNOWN], ["Risk version", pretrade.qualification?.ruleVersion ?? UNKNOWN], ["Expiry", pretrade.expiry ?? UNKNOWN]].map(([label, value]) => <div key={label}><span>{label}</span><strong>{value}</strong></div>)}</div><div className="review-hash"><span>Plan binding</span><code>{pretrade.planHash ?? `${planHash(pretrade).slice(0, 20)}â€¦`}</code></div>{wallet.state.status === "DISCONNECTED" && <button className="button button-primary button-wide" onClick={() => void wallet.connect()}>Connect wallet to sign</button>}{wallet.state.status === "WRONG_NETWORK" && <button className="button button-primary button-wide" onClick={() => void wallet.switchToArc()}>Switch to {WINNER_CONFIG.chainName}</button>}{wallet.state.status === "CONNECTED" && <button className="button button-primary button-wide" onClick={() => void sign()}>{flow === "WAITING_KEEPER" ? "Waiting for keeper" : flow === "FAILED" ? "Retry after review" : "Sign & submit"}</button>}<div className="flow-line"><span className={flow === "DRAFT" ? "active" : ""}>Review</span><span className={flow === "AWAITING_SIGNATURE" ? "active" : ""}>Sign</span><span className={flow === "PENDING_CHAIN" ? "active" : ""}>Chain</span><span className={flow === "WAITING_KEEPER" ? "active" : ""}>Keeper</span></div></div></div>}</aside>;
}

function MarketDetail({ data, wallet, watchlist }: { data: ReturnType<typeof useProductData>; wallet: ReturnType<typeof useWallet>; watchlist: ReturnType<typeof useWatchlist> }) {
  const { marketId } = useParams(); const [market, setMarket] = useState<OriginMarket | null>(null); const [tab, setTab] = useState("Overview"); const [provenance, setProvenance] = useState<PassportRow | null>(null);
  useEffect(() => { if (!marketId) return; void api.market(decodeURIComponent(marketId)).then((raw) => setMarket(normalize(raw))).catch(() => setMarket(data.page.items.find((item) => item.marketId === marketId) ?? null)); }, [marketId, data.page.items]);
  if (!market) return <section className="page"><Empty title="Market unavailable" copy="No market was returned for this chain and canonical address." /></section>;
  const state = productState(market); const tabs = ["Overview", "Trades", "Holders", "Risk", "Liquidity", "Deployer", "Proof"];
  return <section className="page detail-page"><div className="detail-header"><div className="detail-token"><TokenAvatar market={market} large /><div><div className="eyebrow">{chainLabel(market.chain)} Â· {lifecycleLabel(market.lifecycle.status)} Â· {market.originPlatform ?? "Origin venue unavailable"}</div><h1>{market.name ?? "Unknown market"} <span>{market.symbol ? `$${market.symbol}` : ""}</span></h1><div className="address-line"><code>{market.tokenAddress}</code><button className="copy-button" onClick={() => void navigator.clipboard?.writeText(market.tokenAddress)} aria-label="Copy token address">Copy</button></div><span className="micro">Observed {ageLabel(market.lifecycle.observedAt)} Â· identity is chain + address</span></div></div><div className="detail-actions"><button className={`watch-button ${watchlist.has(market.marketId) ? "saved" : ""}`} onClick={() => watchlist.toggle(market.marketId)}>{watchlist.has(market.marketId) ? "â˜… Saved" : "â˜† Watch"}</button><StatusPill value={state.label} tone={state.tone} label={state.label} /></div></div><div className="detail-stats"><Metric label="Price" value={displayed(market.priceUsd, formatUsd)} /><Metric label="24h" value={market.priceChange24hBps === null ? UNKNOWN : formatPercentBps(market.priceChange24hBps)} /><Metric label="Liquidity" value={displayed(market.originSpotLiquidityUsd, formatUsd)} note="Origin spot" /><Metric label="24h volume" value={displayed(market.volume24hUsd, formatUsd)} /><Metric label="Transactions" value={market.transactions24h === null ? UNKNOWN : formatDecimal(String(market.transactions24h), 0)} /><Metric label="Freshness" value={market.freshness.status} /></div><div className="detail-grid"><div className="detail-main"><section className="panel chart-panel"><div className="panel-heading"><div><div className="eyebrow">Observed price</div><h2>Market chart</h2></div><span className="micro">{market.history.length ? `${market.history.length} real observations` : "Real history unavailable"}</span></div><MiniChart history={market.history} /></section><div className="tabs" role="tablist">{tabs.map((item) => <button key={item} className={tab === item ? "active" : ""} onClick={() => setTab(item)} role="tab" aria-selected={tab === item}>{item}</button>)}</div><DetailEvidence tab={tab} market={market} onProvenance={setProvenance} /></div><TradingRail market={market} wallet={wallet} /></div>{provenance && <ProvenanceDrawer market={market} row={provenance} onClose={() => setProvenance(null)} />}</section>;
}

function Landing({ data }: { data: ReturnType<typeof useProductData> }) { const preview = data.page.items[0]; return <section className="landing-page"><nav className="landing-nav"><Logo /><div className="landing-links"><Link to="/markets">Markets</Link><Link to="/new">New</Link><Link to="/proof">How it works</Link></div><Link className="button button-primary compact" to="/markets">Explore markets</Link></nav><div className="landing-hero"><div><div className="eyebrow">Multichain meme-market intelligence</div><h1>Discover meme markets.<br /><em>Trade only what earns it.</em></h1><p>See the origin market, understand its evidence, and find out which tokens are safe enough for leverage. ArcMemePerps keeps discovery fast and execution gated.</p><div className="hero-actions"><Link className="button button-primary" to="/markets">Explore markets â†—</Link><Link className="button button-secondary" to="/proof">How qualification works</Link></div><div className="landing-truth"><span><b>{data.page.discoveryCount ?? "â€”"}</b> markets observed</span><span><b>{data.page.perpCount ?? 0}</b> live perps</span><span>Arc USDC settlement</span></div></div><div className="hero-preview">{preview ? <><div className="preview-top"><span>LIVE DISCOVERY</span><StatusPill value={productState(preview).label} tone={productState(preview).tone} label={productState(preview).label} /></div><div className="preview-token"><TokenAvatar market={preview} large /><div><strong>{preview.symbol ?? "Unknown"}</strong><span>{preview.name ?? "Name unavailable"}</span><small>{chainLabel(preview.chain)} Â· {lifecycleLabel(preview.lifecycle.status)}</small></div></div><div className="preview-price"><strong>{displayed(preview.priceUsd, formatUsd)}</strong><span className={preview.priceChange24hBps !== null && preview.priceChange24hBps >= 0 ? "positive" : "muted-text"}>{preview.priceChange24hBps === null ? UNKNOWN : formatPercentBps(preview.priceChange24hBps)} today</span></div><div className="preview-grid"><Metric label="Liquidity" value={displayed(preview.originSpotLiquidityUsd, formatUsd)} /><Metric label="24h volume" value={displayed(preview.volume24hUsd, formatUsd)} /><Metric label="Evidence" value={preview.integrity.status === "PENDING" ? "Partial" : preview.integrity.status} /></div><div className="preview-footer"><span>Canonical token identity</span><code>{shorten(preview.tokenAddress, 8)}</code></div></> : <div className="preview-loading"><span className="skeleton-line" /><span className="skeleton-line short" /><span className="skeleton-block" /></div>}</div></div><div className="landing-flow"><div><span className="eyebrow">The product loop</span><h2>Fast discovery.<br />Visible evidence.</h2></div>{[["01", "Discover", "Real origin markets, normalized by chain and canonical token identity."], ["02", "Understand", "Risk passport, holders, liquidity, history, and coverage in one terminal."], ["03", "Qualify", "Only evidence-backed markets can earn an Arc perp state."], ["04", "Execute", "Review â†’ wallet sign â†’ keeper â†’ chain â†’ reconcile."]].map(([number, title, copy]) => <div className="flow-step" key={number}><span>{number}</span><h3>{title}</h3><p>{copy}</p></div>)}</div><footer className="landing-footer"><span>ArcMemePerps Â· ARC MAINNET</span><span>Discovery remains useful even when perps are at 0.</span></footer></section>; }

function WalletEmpty({ title, copy, wallet }: { title: string; copy: string; wallet: ReturnType<typeof useWallet> }) { return <div className="panel"><Empty title={title} copy={copy} action={wallet.state.status === "DISCONNECTED" ? <button className="button button-primary" onClick={() => void wallet.connect()}>Connect wallet</button> : undefined} /></div>; }
function Portfolio({ wallet }: { wallet: ReturnType<typeof useWallet> }) { const [state, setState] = useState<{ value: unknown; loading: boolean; error: string | null }>({ value: null, loading: false, error: null }); useEffect(() => { if (!wallet.state.address) return; setState({ value: null, loading: true, error: null }); void api.portfolio(wallet.state.address).then((value) => setState({ value, loading: false, error: null })).catch((errorValue) => setState({ value: null, loading: false, error: errorValue instanceof Error ? errorValue.message : "API_UNAVAILABLE" })); }, [wallet.state.address]); if (!wallet.state.address) return <section className="page"><PageIntro eyebrow="Portfolio" title="Your risk, reconciled." copy="Connect a wallet to see canonical collateral, positions, and orders." /><WalletEmpty title="Connect to view your portfolio" copy="No wallet-specific balances or positions are inferred while disconnected." wallet={wallet} /></section>; const value = record(state.value); return <section className="page"><PageIntro eyebrow="Portfolio" title="Your risk, reconciled." copy={`Wallet ${shorten(wallet.state.address, 8)} Â· canonical Product records only`} /><div className="portfolio-grid"><Metric label="Equity" value={textValue(value.equityUsd, UNKNOWN)} /><Metric label="Available collateral" value={textValue(value.availableCollateralUsd, UNKNOWN)} /><Metric label="Unrealized PnL" value={textValue(value.unrealizedPnlUsd, UNKNOWN)} /><Metric label="Open positions" value={textValue(value.positionCount, UNKNOWN)} /></div>{state.loading ? <div className="panel"><div className="resource-state"><span className="skeleton-line" /><span className="skeleton-line short" /></div></div> : state.error ? <div className="notice notice-bad"><b>Portfolio unavailable.</b><span>{state.error}</span></div> : <div className="panel"><Empty title="No open ArcMemePerps positions" copy="There are no canonical positions to display for this wallet. Future equity, collateral, orders, and positions will appear here after a real live perp flow." /></div>}</section>; }
function Activity({ wallet }: { wallet: ReturnType<typeof useWallet> }) { const [state, setState] = useState<{ value: unknown; loading: boolean; error: string | null }>({ value: null, loading: false, error: null }); useEffect(() => { if (!wallet.state.address) return; setState({ value: null, loading: true, error: null }); void api.activity(wallet.state.address).then((value) => setState({ value, loading: false, error: null })).catch((errorValue) => setState({ value: null, loading: false, error: errorValue instanceof Error ? errorValue.message : "API_UNAVAILABLE" })); }, [wallet.state.address]); if (!wallet.state.address) return <section className="page"><PageIntro eyebrow="Activity" title="A clear record of what happened." copy="User-readable events from the canonical Product deployment." /><WalletEmpty title="Connect to view activity" copy="Wallet activity is not inferred from a disconnected browser." wallet={wallet} /></section>; const value = record(state.value); const items = Array.isArray(value.items) ? value.items : []; return <section className="page"><PageIntro eyebrow="Activity" title="A clear record of what happened." copy="Orders, fills, funding, and positions appear only when indexed from canonical records." />{state.loading ? <div className="panel"><div className="resource-state"><span className="skeleton-line" /></div></div> : state.error ? <div className="notice notice-bad"><b>Activity unavailable.</b><span>{state.error}</span></div> : items.length ? <div className="activity-list">{items.map((item, index) => { const row = record(item); return <article key={textValue(row.id, String(index))}><span className="activity-icon">Â·</span><div><b>{textValue(row.type ?? row.kind, "Activity event")}</b><p>{textValue(row.reason ?? row.message, "Canonical deployment event")}</p></div><time>{textValue(row.createdAt ?? row.occurredAt, UNKNOWN)}</time></article>; })}</div> : <div className="panel"><Empty title="No activity yet" copy="No canonical user events were returned for this wallet." /></div>}</section>; }

function Proof() { return <section className="page proof-page"><PageIntro eyebrow="Protocol / proof" title="The product shows its work." copy="Discovery is public. Perp execution is earned through evidence, capacity, and an immutable review before signing." /><div className="proof-banner"><div><span className="eyebrow">Current product truth</span><h2>0 registered live perp markets</h2><p>That is an intentional state. Markets remain useful for discovery and intelligence while no token currently satisfies the live-perp policy.</p></div><Link to="/markets" className="button button-primary">Explore discovery</Link></div><div className="proof-grid"><div className="proof-card"><span className="eyebrow">Qualification</span><h2>Evidence before leverage</h2><p>Core token safety, market quality, evidence coverage, and derivatives capacity stay separate. Unknown data is never converted into a pass.</p><div className="proof-list"><span>Policy version <b>{WINNER_CONFIG.riskRuleVersion}</b></span><span>Oracle requirement <b>2-of-3 reporters</b></span><span>Live markets <b>0</b></span><span>Mainnet writes <b>None in this phase</b></span></div></div><div className="proof-card"><span className="eyebrow">Security evidence</span><h2>Adversarial controls</h2><p>Protocol evidence remains available for readers who want the deeper accounting and fail-closed state transitions.</p><div className="proof-list"><span>State <b>{String(STRESS_EVIDENCE.solvencyBlocked ? "Separated from product" : "Unavailable")}</b></span><span>Bad debt observation <b>{STRESS_EVIDENCE.badDebtBaseUnits} base units</b></span><span>Live write path <b>Disabled without qualification</b></span></div></div></div><details className="advanced-details large"><summary>How a market becomes a live perp</summary><div className="advanced-grid"><div><span>01 Â· Discovered</span><code>Observed on an origin chain</code></div><div><span>02 Â· Core safety</span><code>Integrity and evidence gates pass</code></div><div><span>03 Â· Derivatives capacity</span><code>Oracle, depth, liquidity, and safe OI are sufficient</code></div><div><span>04 Â· Qualified</span><code>Fresh 0.4.0 proof is accepted</code></div><div><span>05 Â· Arc activation</span><code>Registry and risk state are changed through governance</code></div><div><span>06 Â· Live perp</span><code>Only then can bounded orders be accepted</code></div></div></details><details className="advanced-details large"><summary>Advanced deployment details</summary><div className="advanced-grid"><div><span>Product deployment</span><code>{WINNER_CONFIG.deploymentId}</code></div><div><span>Chain</span><code>{WINNER_CONFIG.chainName} Â· {WINNER_CONFIG.chainId}</code></div><div><span>Contract source</span><code>{shorten(WINNER_CONFIG.contractSourceSha, 14)}</code></div><div><span>Settlement</span><code>Arc USDC</code></div></div></details></section>; }
function SimplePage({ title, eyebrow, copy }: { title: string; eyebrow: string; copy: string }) { return <section className="page"><PageIntro eyebrow={eyebrow} title={title} copy={copy} /><div className="panel"><Empty title="No indexed records" copy="This surface will show canonical Product records when the relevant user or protocol data exists. It does not invent participants, balances, or activity." /></div></section>; }

function AppRoute({ data, wallet, watchlist }: { data: ReturnType<typeof useProductData>; wallet: ReturnType<typeof useWallet>; watchlist: ReturnType<typeof useWatchlist> }) { const location = useLocation(); const params = new URLSearchParams(location.search); if (location.pathname === "/markets") return <MarketExplorer data={data} refresh={data.refresh} error={data.error} search={params.get("q") ?? undefined} view="MARKETS" watchlist={watchlist} />; if (location.pathname === "/new") return <MarketExplorer data={data} refresh={data.refresh} error={data.error} search={params.get("q") ?? undefined} view="NEW" watchlist={watchlist} />; if (location.pathname === "/watchlist") return <MarketExplorer data={data} refresh={data.refresh} error={data.error} search={params.get("q") ?? undefined} view="WATCHLIST" watchlist={watchlist} />; if (location.pathname.startsWith("/markets/")) return <MarketDetail data={data} wallet={wallet} watchlist={watchlist} />; if (location.pathname === "/proof") return <Proof />; if (location.pathname === "/portfolio") return <Portfolio wallet={wallet} />; if (location.pathname === "/activity") return <Activity wallet={wallet} />; if (location.pathname === "/earn") return <SimplePage eyebrow="Earn / LP" title="Liquidity with the full picture." copy="Liquidity is an economic counterparty to traders. NAV, liabilities, insurance, and withdrawable liquidity belong together." />; if (location.pathname.startsWith("/profile")) return <SimplePage eyebrow="Profile" title="Wallet-native performance." copy="Realized PnL, return, and risk-adjusted performance stay separate and appear only from canonical records." />; if (location.pathname.startsWith("/competitions")) return <SimplePage eyebrow="Competitions" title="Compare the right metric." copy="Rankings will use canonical activity only. No vanity stats are shown while the history is incomplete." />; if (location.pathname === "/settings") return <SimplePage eyebrow="Settings" title="Preferences and network." copy="Wallet signing stays in your browser. Reporter, keeper, and deployer secrets never enter this application." />; return <MarketExplorer data={data} refresh={data.refresh} error={data.error} view="MARKETS" watchlist={watchlist} />; }
export function WinnerApp() { const data = useProductData(); const wallet = useWallet(); const watchlist = useWatchlist(); const navigate = useNavigate(); return <Routes><Route path="/" element={<Landing data={data} />} /><Route element={<Shell wallet={wallet} stream={data.stream} onSearch={(value) => { void navigate(`/markets?q=${encodeURIComponent(value)}`); }} />}><Route path="markets/:marketId" element={<MarketDetail data={data} wallet={wallet} watchlist={watchlist} />} /><Route path="*" element={<AppRoute data={data} wallet={wallet} watchlist={watchlist} />} /></Route></Routes>; }
